def quantile(self, q=0.5, axis=0, numeric_only=True, interpolation="linear"):
    self._check_percentile(q)

    # Instead of trying to get numeric data, check if numeric_only is False
    # Allow for datetime and timedelta when numeric_only is False
    if numeric_only:
        data = self._get_numeric_data()
    else:
        data = self

    # If no columns exist (i.e., empty DataFrame), return empty results
    if data.shape[1] == 0:
        if isinstance(q, list):
            return self._constructor(pd.DataFrame([], index=q))
        return self._constructor_sliced(pd.Series([], index=[], name=q))

    axis = self._get_axis_number(axis)
    is_transposed = axis == 1

    if is_transposed:
        data = data.T

    # Compute quantiles on data
    result = data._data.quantile(
        qs=q, axis=1, interpolation=interpolation, transposed=is_transposed
    )

    if result.ndim == 2:
        result = self._constructor(result)
    else:
        result = self._constructor_sliced(result, name=q)

    if is_transposed:
        result = result.T

    return result
